package com.generated.orion.runtime;

import com.appruntime.MqService;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.concurrent.atomic.AtomicBoolean;

/**
 * No JMS broker configured: answer every MQ verb with the same MQ-level codes the online runtime's
 * stub mode uses, so the COBOL logic takes its ordinary error branches (MQGET → no message → leave
 * the loop; MQPUT → OK). Warns once. Generated by Cobol2Java.
 */
public class MqStubService implements MqService {

    private static final Logger log = LoggerFactory.getLogger(MqStubService.class);
    private static final int MQCC_OK = 0,
            MQCC_FAILED = 2,
            MQRC_NONE = 0,
            MQRC_NO_MSG_AVAILABLE = 2033;
    private final AtomicBoolean warned = new AtomicBoolean();

    private void warn(String verb) {
        if (warned.compareAndSet(false, true)) {
            log.warn(
                    "MQ CALL '{}' — no JMS broker configured (no JmsTemplate bean); stub mode: "
                            + "OPEN/PUT/CLOSE report success, GET reports MQRC_NO_MSG_AVAILABLE",
                    verb);
        }
    }

    /** [hconn, objDesc, options, hobj(out), compCode(out), reason(out)] */
    @Override
    public void mqOpen(Object[] p) {
        warn("MQOPEN");
        set(p, 3, 1);
        set(p, 4, MQCC_OK);
        set(p, 5, MQRC_NONE);
    }

    /**
     * [hconn, hobj, msgDesc, getOpts, buffLen, buffer(out), dataLen(out), compCode(out),
     * reason(out)]
     */
    @Override
    public void mqGet(Object[] p) {
        warn("MQGET");
        set(p, 5, "");
        set(p, 6, 0);
        set(p, 7, MQCC_FAILED);
        set(p, 8, MQRC_NO_MSG_AVAILABLE);
    }

    /** [hconn, hobj, msgDesc, putOpts, buffLen, buffer, compCode(out), reason(out)] */
    @Override
    public void mqPut(Object[] p) {
        warn("MQPUT");
        set(p, 6, MQCC_OK);
        set(p, 7, MQRC_NONE);
    }

    /** [hconn, objDesc, msgDesc, putOpts, buffLen, buffer, compCode(out), reason(out)] */
    @Override
    public void mqPut1(Object[] p) {
        warn("MQPUT1");
        set(p, 6, MQCC_OK);
        set(p, 7, MQRC_NONE);
    }

    /** [hconn, hobj, closeOpts, compCode(out), reason(out)] */
    @Override
    public void mqClose(Object[] p) {
        warn("MQCLOSE");
        set(p, 3, MQCC_OK);
        set(p, 4, MQRC_NONE);
    }

    private static void set(Object[] p, int i, Object v) {
        if (p != null && p.length > i) p[i] = v;
    }
}
